package com.yilu.yinling.knowledge.service.impl;
import com.yilu.yinling.ai.rag.*; import com.yilu.yinling.knowledge.parser.*; import com.yilu.yinling.knowledge.service.KnowledgeService; import com.yilu.yinling.knowledge.splitter.TextSplitter; import com.yilu.yinling.knowledge.vo.KnowledgeUploadResponse; import com.yilu.yinling.storage.FileStorageService; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@Service public class KnowledgeServiceImpl implements KnowledgeService {
 private final List<DocumentParser> parsers; private final TextSplitter splitter; private final EmbeddingService embedding; private final VectorStore vectorStore; private final FileStorageService storage;
 public KnowledgeServiceImpl(List<DocumentParser> p,TextSplitter s,EmbeddingService e,VectorStore v,FileStorageService fs){parsers=p;splitter=s;embedding=e;vectorStore=v;storage=fs;}
 public KnowledgeUploadResponse upload(MultipartFile file){if(file==null||file.isEmpty())throw new IllegalArgumentException("文件不能为空"); storage.upload(file); DocumentParser parser=parsers.stream().filter(p->p.supports(file.getOriginalFilename(),file.getContentType())).findFirst().orElseThrow(()->new IllegalArgumentException("仅支持PDF、TXT、Markdown")); List<String> chunks=splitter.split(parser.parse(file)); String id=UUID.randomUUID().toString(); for(int i=0;i<chunks.size();i++){String chunkId=id+"-"+i; vectorStore.save(chunkId,chunks.get(i),embedding.embed(chunks.get(i)));} return new KnowledgeUploadResponse(id,chunks.size(),"SUCCESS");}
}
